begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
select ('a9000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','rules-'||n||'@example.invalid','x',now(),now(),now() from generate_series(1,3) n;
insert into public.staff_users(user_id,role) values('a9000000-0000-4000-8000-000000000001','office'),('a9000000-0000-4000-8000-000000000002','technician'),('a9000000-0000-4000-8000-000000000003','technician');
insert into public.customers(id,name) values('c9000000-0000-4000-8000-000000000001','Klient Reguły');
create function pg_temp.item(p uuid) returns jsonb language sql as $$select i from jsonb_array_elements(public.stock_overview()->'items') i where (i->>'id')::uuid=p$$;
create function pg_temp.lvl(p uuid,loc uuid) returns numeric language sql as $$select coalesce((pg_temp.item(p)->'levels'->>loc::text)::numeric,0)$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000001',true);
select public.save_stock_item('19000000-0000-4000-8000-000000000001','RG-R32','R32','refrigerant','kg',0,'','HFC',675,'butla 9 kg');
select public.save_stock_item('19000000-0000-4000-8000-000000000002','RG-ZL','Złączka','parts','szt.',0,'','',null,'');
select public.save_stock_vehicle('29000000-0000-4000-8000-000000000001','a9000000-0000-4000-8000-000000000002','Bus A','');
select public.save_stock_vehicle('29000000-0000-4000-8000-000000000002','a9000000-0000-4000-8000-000000000003','Bus B','');
select lives_ok($$select public.save_stock_item('19000000-0000-4000-8000-000000000002','RG-ZL','Złączka','parts','kpl',0,'','',null,'')$$,'Unit can change before the first movement');
select public.post_stock_document('39000000-0000-4000-8000-000000000001','PZ',null,'5e000000-0000-4000-8000-000000000001',null,'Hurtownia','','[{"itemId":"19000000-0000-4000-8000-000000000001","quantity":10,"cylinder":"B-0417"},{"itemId":"19000000-0000-4000-8000-000000000002","quantity":5}]');
select is(pg_temp.item('19000000-0000-4000-8000-000000000001')->>'unitLocked','true','Item with a movement has a locked unit');
select throws_ok($$select public.save_stock_item('19000000-0000-4000-8000-000000000002','RG-ZL','Złączka','parts','szt.',0,'','',null,'')$$,'22023',null,'Unit change refused after the first movement');
select is(public.stock_item_moves('19000000-0000-4000-8000-000000000001')->0->>'cylinder','B-0417','Cylinder number kept on the movement');
select lives_ok($$select public.set_stock_vehicle_min('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001',3)$$,'Office sets a van minimum');
select lives_ok($$select public.set_stock_vehicle_min('29000000-0000-4000-8000-000000000002','19000000-0000-4000-8000-000000000002',2)$$,'Minimum in the second van');
select is((pg_temp.item('19000000-0000-4000-8000-000000000001')->'vehicleMins'->>'29000000-0000-4000-8000-000000000001')::numeric,3::numeric,'Overview shows the van minimum');
select is(jsonb_array_length(public.refill_vehicles('49000000-0000-4000-8000-000000000001')),2,'Refill posts one MM per van with shortages');
select is(pg_temp.lvl('19000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001'),3::numeric,'Van A refilled to minimum');
select is(pg_temp.lvl('19000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000002'),2::numeric,'Van B refilled to minimum');
select is(jsonb_array_length(public.refill_vehicles('49000000-0000-4000-8000-000000000001')),2,'Retry returns the same documents');
select is(pg_temp.lvl('19000000-0000-4000-8000-000000000001','5e000000-0000-4000-8000-000000000001'),7::numeric,'Retry does not move stock twice');
select is(jsonb_array_length(public.refill_vehicles('49000000-0000-4000-8000-000000000002')),0,'Nothing to refill when vans are at minimum');
select throws_ok($$select public.post_stock_document('39000000-0000-4000-8000-000000000002','WZ','5e000000-0000-4000-8000-000000000001',null,null,'','','[{"itemId":"19000000-0000-4000-8000-000000000002","quantity":1}]')$$,'22023',null,'WZ needs a recipient');
select alike(public.post_stock_document('39000000-0000-4000-8000-000000000002','WZ','5e000000-0000-4000-8000-000000000001',null,null,'Sklep Polna','','[{"itemId":"19000000-0000-4000-8000-000000000002","quantity":1}]','c9000000-0000-4000-8000-000000000001')->>'number','WZ/%','External issue gets a WZ number');
select is(pg_temp.lvl('19000000-0000-4000-8000-000000000002','5e000000-0000-4000-8000-000000000001'),2::numeric,'WZ takes stock out');
select is(public.save_stock_draft('39000000-0000-4000-8000-000000000003','RW','{"qty":"1"}')->>'kind','RW','Draft saved');
select is(jsonb_array_length(public.stock_overview()->'drafts'),1,'Author sees the draft');
select public.save_crm_record('c9000000-0000-4000-8000-000000000001','tasks','b9000000-0000-4000-8000-000000000001',null,jsonb_build_object('title','Zamówić butlę','description','','kind','general','dueOn',to_char((now() at time zone 'Europe/Warsaw')::date,'YYYY-MM-DD'),'assigneeId','a9000000-0000-4000-8000-000000000001','contactId',null,'state','todo','result',''));
select lives_ok($$select public.reserve_stock_for_task('59000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','b9000000-0000-4000-8000-000000000001',1)$$,'Office reserves for a task');
select is(pg_temp.item('19000000-0000-4000-8000-000000000001')->'reservations'->0->>'taskId','b9000000-0000-4000-8000-000000000001','Reservation shows the task');
select ok(exists(select 1 from jsonb_array_elements(public.stock_task_options()) t where t->>'id'='b9000000-0000-4000-8000-000000000001'),'Task offered for reservations');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select is(jsonb_array_length(public.stock_overview()->'drafts'),0,'Other people do not see the draft');
select throws_ok($$select public.save_stock_draft('39000000-0000-4000-8000-000000000003','RW','{}')$$,'42501',null,'Cannot overwrite another person''s draft');
select throws_ok($$select public.set_stock_vehicle_min('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001',5)$$,'42501',null,'Technician cannot set minimums');
select throws_ok($$select public.refill_vehicles(gen_random_uuid())$$,'42501',null,'Technician cannot refill');
select throws_ok($$select public.post_stock_document(gen_random_uuid(),'WZ','29000000-0000-4000-8000-000000000001',null,null,'Ktoś','','[{"itemId":"19000000-0000-4000-8000-000000000001","quantity":1}]')$$,'42501',null,'Technician cannot post WZ');
select * from finish();
rollback;
